3	//  SwiftMandarin
4	//
5	//  A reusable view component that displays AI-generated word explanations
6	//  using either Apple Intelligence or Ollama based on user settings
7	//
8	
9	import SwiftUI
10	
11	/// A view that displays a detailed AI-generated explanation for a Mandarin word
12	struct AIWordExplanationView: View {
13	    let word: String
14	    let pinyin: String
15	    let context: String?
16	    
17	    @State private var explanation: WordExplanationResult?
18	    @State private var isLoading: Bool = false
19	    @State private var errorMessage: String?
20	    @State private var expandedSections: Set<String> = ["definition", "examples"]
21	    /// True when the currently shown explanation came from the persistent cache
22	    /// rather than a fresh generation, so the UI can label it.
23	    @State private var servedFromCache: Bool = false
24	    /// Direction token the currently shown explanation belongs to. Lets us drop
25	    /// a stale explanation if the interface language flips while the view is open.
26	    @State private var shownDirection: String?
27	
28	    private let aiService = AIWordExplanationService.shared
29	    private let aiSettings = AIModelSettings.shared
30	    private let cache = WordExplanationCacheStore.shared
31	
32	    /// Direction token for the current word + interface language, used as the
33	    /// per-direction cache key. Recomputed if the language changes while open.
34	    private var directionToken: String {
35	        ExplanationDirection.current(forWord: word).cacheToken
36	    }
37	    
38	    /// Check if any AI provider is available
39	    private var isAnyProviderAvailable: Bool {
40	        aiSettings.isAnyProviderAvailable
41	    }
42	    
43	    /// Get the current provider name for display
44	    private var currentProviderName: String {
45	        aiSettings.effectiveProvider.displayName
46	    }
47	    
48	    var body: some View {
49	        Group {
50	            if !isAnyProviderAvailable {
51	                unavailableView
52	            } else if isLoading {
53	                loadingView
54	            } else if let error = errorMessage {
55	                errorView(error)
56	            } else if let explanation = explanation {
57	                explanationContent(explanation)
58	            } else {
59	                generateButton
60	            }
61	        }
62	        // Serve a previously generated explanation instantly, without another
63	        // AI round-trip. Re-runs if the direction (interface language) changes
64	        // while the view is open. Never overrides a fresh in-memory result.
65	        .task(id: directionToken) {
66	            loadCachedExplanationIfAvailable()
67	        }
68	    }
69	    
70	    // MARK: - Unavailable State
71	    
72	    private var unavailableView: some View {
73	        VStack(spacing: 12) {
74	            Image(systemName: "cpu")
75	                .font(.system(size: 32))
76	                .foregroundStyle(.secondary)
77	            
78	            Text("AI Not Available")
79	                .font(.headline)
80	            
81	            Text("Enable Apple Intelligence or connect to Ollama in Settings to use AI features.")
82	                .font(.caption)
83	                .foregroundStyle(.secondary)
84	                .multilineTextAlignment(.center)
85	        }
86	        .padding()
87	        .frame(maxWidth: .infinity)
88	    }
89	    
90	    // MARK: - Loading State
91	    
92	    private var loadingView: some View {
93	        VStack(spacing: 16) {
94	            ProgressView()
95	                .controlSize(.large)
96	            
97	            Text("Generating explanation...")
98	                .font(.subheadline)
99	                .foregroundStyle(.secondary)
100	            
101	            Text("Using \(currentProviderName)")
102	                .font(.caption2)
