498	    /// Reconcile the view with the current direction: if a previously shown
499	    /// explanation belongs to a now-stale direction (interface language flipped),
500	    /// drop it; then serve this direction's cached explanation if one exists and
501	    /// nothing fresh is already shown. Safe to call repeatedly.
502	    private func loadCachedExplanationIfAvailable() {
503	        if let shown = shownDirection, shown != directionToken {
504	            explanation = nil
505	            errorMessage = nil
506	            servedFromCache = false
507	            shownDirection = nil
508	        }
509	        guard explanation == nil, !isLoading else { return }
510	        guard let cached = cache.explanation(forWord: word, directionToken: directionToken) else { return }
511	        explanation = cached.result
512	        errorMessage = nil
513	        servedFromCache = true
514	        shownDirection = directionToken
515	    }
