517	    /// Generate a fresh explanation (always bypasses the cache — this is also
518	    /// the "regenerate" path) and persist the result for instant reuse later.
519	    private func generateExplanation() async {
520	        isLoading = true
521	        errorMessage = nil
522	        servedFromCache = false
523	
524	        do {
525	            // Use the unified provider method that routes to Apple Intelligence or Ollama
526	            let result = try await aiService.generateExplanationWithProvider(
527	                for: word,
528	                pinyin: pinyin,
529	                context: context
530	            )
531	            explanation = result
532	            shownDirection = directionToken
533	            cache.store(
534	                word: word,
535	                pinyin: pinyin,
536	                directionToken: directionToken,
537	                providerName: aiSettings.effectiveProvider.displayName,
538	                result: result
539	            )
540	        } catch {
541	            errorMessage = error.localizedDescription
542	        }
543	
544	        isLoading = false
545	    }
546	}
