260	/// Observable settings for AI model configuration.
261	@Observable
262	@MainActor
263	final class AIModelSettings {
264	
265	    static let shared = AIModelSettings()
266	
267	    // MARK: - UserDefaults Keys
268	
269	    private enum Keys {
270	        static let provider = "ai_provider"
271	        static let ollamaModel = "ollama_model"
272	        static let ollamaHost = "ollama_host"
273	        static let enableThinking = "ollama_enable_thinking"
274	        static let contextLength = "ollama_context_length"
275	        static let cloudModels = "cloud_model_selections"   // [providerRaw: modelID]
276	        static let cloudBaseURLs = "cloud_base_overrides"   // [providerRaw: baseURL]
277	        static let cloudAPIStyles = "cloud_api_style_overrides" // [providerRaw: "openai"|"anthropic"]
278	        static let aiPhotoCleanup = "ai_photo_cleanup_enabled"
279	    }
280	
281	    // MARK: - Properties
282	
283	    /// The currently selected AI provider.
284	    var provider: AIProvider {
285	        didSet { UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider) }
286	    }
287	
288	    /// The selected Ollama model name.
289	    var ollamaModel: String {
290	        didSet { UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel) }
291	    }
292	
293	    /// The Ollama server host URL.
294	    var ollamaHost: String {
295	        didSet {
296	            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
297	            updateOllamaServiceHost()
298	        }
299	    }
300	
301	    /// Whether to enable thinking/reasoning mode for Ollama models.
302	    var enableThinking: Bool {
303	        didSet { UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking) }
304	    }
305	
306	    /// Context length for Ollama models (in tokens).
307	    var contextLength: Int {
308	        didSet { UserDefaults.standard.set(contextLength, forKey: Keys.contextLength) }
309	    }
310	
311	    /// When enabled, uploaded photos are passed through the selected AI
312	    /// provider for OCR cleanup/structuring before downstream processing.
313	    var aiPhotoCleanupEnabled: Bool {
314	        didSet { UserDefaults.standard.set(aiPhotoCleanupEnabled, forKey: Keys.aiPhotoCleanup) }
315	    }
316	
317	    /// Per-provider selected cloud model IDs.
318	    private(set) var cloudModelSelections: [String: String] {
319	        didSet { persistDictionary(cloudModelSelections, key: Keys.cloudModels) }
320	    }
321	
322	    /// Per-provider base URL overrides (empty entry → use provider default).
323	    private(set) var cloudBaseURLOverrides: [String: String] {
324	        didSet { persistDictionary(cloudBaseURLOverrides, key: Keys.cloudBaseURLs) }
325	    }
326	
327	    /// Per-provider API-format overrides ("openai" / "anthropic"). When absent,
328	    /// the provider's built-in style is used. Lets users point a provider at an
329	    /// Anthropic-compatible gateway (e.g. a Kimi "coding" endpoint).
330	    private(set) var apiStyleOverrides: [String: String] {
331	        didSet { persistDictionary(apiStyleOverrides, key: Keys.cloudAPIStyles) }
332	    }
333	
334	    /// In-memory mirror of Keychain API keys so SwiftUI reacts to changes.
335	    /// Loaded from the Keychain at init; writes go through to the Keychain.
336	    private(set) var apiKeys: [String: String] = [:]
337	
338	    // MARK: - Initialization
339	
340	    private init() {
341	        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
342	        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence
343	
344	        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
345	        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
346	        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
347	        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000
348	        self.aiPhotoCleanupEnabled = UserDefaults.standard.object(forKey: Keys.aiPhotoCleanup) as? Bool ?? false
349	
350	        self.cloudModelSelections = AIModelSettings.loadDictionary(key: Keys.cloudModels)
351	        self.cloudBaseURLOverrides = AIModelSettings.loadDictionary(key: Keys.cloudBaseURLs)
352	        self.apiStyleOverrides = AIModelSettings.loadDictionary(key: Keys.cloudAPIStyles)
353	
354	        // Load API keys from Keychain into the observable mirror.
355	        var keys: [String: String] = [:]
356	        for p in AIProvider.allCases where p.isCloud {
357	            if let value = KeychainHelper.get(account: p.keychainAccount), !value.isEmpty {
358	                keys[p.rawValue] = value
359	            }
360	        }
361	        self.apiKeys = keys
362	
363	        updateOllamaServiceHost()
364	    }
365	
366	    // MARK: - Per-Provider Accessors
367	
368	    /// The API key for a cloud provider (empty string when none).
369	    func apiKey(for provider: AIProvider) -> String {
370	        apiKeys[provider.rawValue] ?? ""
371	    }
372	
373	    /// Store or clear a cloud provider's API key (Keychain + observable mirror).
374	    func setAPIKey(_ value: String, for provider: AIProvider) {
375	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
376	        KeychainHelper.set(trimmed, account: provider.keychainAccount)
377	        if trimmed.isEmpty {
378	            apiKeys.removeValue(forKey: provider.rawValue)
379	        } else {
380	            apiKeys[provider.rawValue] = trimmed
381	        }
382	    }
383	
384	    /// The effective base URL for a cloud provider (override or default).
385	    func baseURL(for provider: AIProvider) -> String {
386	        let override = cloudBaseURLOverrides[provider.rawValue]?.trimmingCharacters(in: .whitespacesAndNewlines)
387	        if let override, !override.isEmpty { return override }
388	        return provider.defaultBaseURL
389	    }
390	
391	    func setBaseURLOverride(_ value: String, for provider: AIProvider) {
392	        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
393	        if trimmed.isEmpty || trimmed == provider.defaultBaseURL {
394	            cloudBaseURLOverrides.removeValue(forKey: provider.rawValue)
395	        } else {
396	            cloudBaseURLOverrides[provider.rawValue] = trimmed
397	        }
398	    }
399	
400	    /// The API-format override for a provider, or nil when using its default.
401	    func apiStyleOverride(for provider: AIProvider) -> AIProviderAPIStyle? {
402	        switch apiStyleOverrides[provider.rawValue] {
403	        case "anthropic": return .anthropic
404	        case "openai": return .openAICompatible
405	        default: return nil
406	        }
407	    }
408	
409	    func setAPIStyleOverride(_ style: AIProviderAPIStyle?, for provider: AIProvider) {
410	        switch style {
411	        case .anthropic: apiStyleOverrides[provider.rawValue] = "anthropic"
412	        case .openAICompatible: apiStyleOverrides[provider.rawValue] = "openai"
413	        case nil: apiStyleOverrides.removeValue(forKey: provider.rawValue)
414	        }
415	    }
416	
417	    /// The effective API style for a provider (override or built-in default).
418	    func effectiveAPIStyle(for provider: AIProvider) -> AIProviderAPIStyle {
419	        apiStyleOverride(for: provider) ?? provider.apiStyle
420	    }
421	
422	    /// Chat path derived from the effective API style.
423	    func effectiveChatPath(for provider: AIProvider) -> String {
424	        switch effectiveAPIStyle(for: provider) {
425	        case .anthropic: return "/v1/messages"
426	        case .openAICompatible: return "/chat/completions"
427	        }
428	    }
429	
430	    /// Models-list path derived from the effective API style.
431	    func effectiveModelsPath(for provider: AIProvider) -> String? {
432	        switch effectiveAPIStyle(for: provider) {
433	        case .anthropic: return "/v1/models"
434	        case .openAICompatible: return provider.modelsPath
435	        }
436	    }
437	
438	    /// Heuristic: does this model id look vision-capable (accepts images)?
439	    static func isLikelyVisionModel(_ id: String) -> Bool {
440	        let l = id.lowercased()
441	        if ["vl", "vision", "omni", "qvq", "4v", "glm-4.5v", "pixtral", "llava", "internvl", "minicpm-v", "gemini"]
442	            .contains(where: { l.contains($0) }) { return true }
443	        // Providers whose flagship chat models are multimodal.
444	        if l.hasPrefix("claude-") || l.contains("gpt-4o") || l.contains("gpt-4.1") || l.hasPrefix("o4") || l.hasPrefix("o3") { return true }
445	        // Doubao multimodal "seed"/vision families.
446	        if l.contains("seed-1-6") || l.contains("seed-1-8") || l.contains("seed-2-") || l.contains("1-5-vision") { return true }
447	        return false
448	    }
449	
450	    /// Resolve a vision-capable model for image tasks: the user's selected model
451	    /// if it's vision-capable, otherwise a vision model from the live list, then
452	    /// the provider's curated default vision model.
453	    func visionModel(for provider: AIProvider) -> String? {
454	        let selected = selectedModel(for: provider)
455	        // Respect the user's selection if it's already a vision model.
456	        if Self.isLikelyVisionModel(selected) { return selected }
457	        // Otherwise prefer the provider's known-good vision model.
458	        if let curated = provider.defaultVisionModel { return curated }
459	        // Last resort: any vision-looking model from the live list.
460	        return CloudAIService.shared.models(for: provider).map(\.id).first(where: Self.isLikelyVisionModel)
461	    }
462	
463	    /// The selected model for a provider. Ollama maps to `ollamaModel`;
464	    /// cloud providers use their per-provider selection (or first default).
465	    func selectedModel(for provider: AIProvider) -> String {
466	        switch provider {
467	        case .ollama:
468	            return ollamaModel
469	        case .appleIntelligence:
470	            return ""
471	        default:
472	            if let chosen = cloudModelSelections[provider.rawValue], !chosen.isEmpty {
473	                return chosen
474	            }
475	            return provider.defaultModels.first ?? ""
476	        }
477	    }
478	
479	    func setSelectedModel(_ model: String, for provider: AIProvider) {
480	        switch provider {
481	        case .ollama:
482	            ollamaModel = model
483	        case .appleIntelligence:
484	            break
485	        default:
486	            cloudModelSelections[provider.rawValue] = model
487	        }
488	    }
489	
490	    // MARK: - Availability
491	
492	    /// Whether Apple Intelligence is available.
493	    var isAppleIntelligenceAvailable: Bool {
494	        #if canImport(FoundationModels)
495	        return AIWordExplanationService.shared.isAvailable
496	        #else
497	        return false
498	        #endif
499	    }
500	
501	    /// Whether a given provider is usable right now.
502	    func isAvailable(_ provider: AIProvider) -> Bool {
503	        switch provider {
504	        case .appleIntelligence:
505	            return isAppleIntelligenceAvailable
506	        case .ollama:
507	            return OllamaService.shared.isConnected
508	        default:
509	            return !apiKey(for: provider).isEmpty
510	        }
511	    }
512	
513	    /// Whether any provider is available for AI features.
514	    var isAnyProviderAvailable: Bool {
515	        AIProvider.allCases.contains { isAvailable($0) }
516	    }
517	
518	    /// Current effective provider — the selected one if usable, otherwise the
519	    /// first available provider, otherwise the selected one (so errors surface).
520	    var effectiveProvider: AIProvider {
521	        if isAvailable(provider) { return provider }
522	        return AIProvider.allCases.first { isAvailable($0) } ?? provider
523	    }
524	
525	    /// Whether Ollama is selected and available.
526	    var isOllamaActive: Bool {
527	        provider == .ollama && OllamaService.shared.isConnected
528	    }
529	
530	    /// Status message for the current configuration.
531	    var statusMessage: String {
532	        switch provider {
533	        case .appleIntelligence:
534	            return isAppleIntelligenceAvailable
535	                ? "Apple Intelligence is ready"
536	                : (AIWordExplanationService.shared.unavailabilityReason ?? "Apple Intelligence is not available")
537	        case .ollama:
538	            if OllamaService.shared.isConnected {
539	                return ollamaModel.isEmpty ? "Connected — select a model" : "Connected to \(ollamaModel)"
540	            }
541	            return OllamaService.shared.connectionError ?? "Not connected to Ollama"
542	        default:
543	            if apiKey(for: provider).isEmpty {
544	                return "Add your \(provider.displayName) API key"
545	            }
546	            let model = selectedModel(for: provider)
547	            return model.isEmpty ? "Ready — select a model" : "Using \(model)"
548	        }
549	    }
550	
551	    /// Options dictionary for Ollama requests based on current settings.
552	    var ollamaOptions: [String: Ollama.Value] {
553	        [
554	            "num_ctx": .int(contextLength),
555	            "temperature": .double(0.7),
556	            "top_p": .double(0.9),
557	            "repeat_penalty": .double(1.1),
558	            "num_predict": .int(-1),
559	        ]
560	    }
561	
562	    // MARK: - Methods
563	
564	    private func updateOllamaServiceHost() {
565	        if let url = URL(string: ollamaHost) {
566	            OllamaService.shared.hostURL = url
567	        }
568	    }
569	
570	    /// Refresh connection and available models for the active provider.
571	    func refreshConnection() async {
572	        switch provider {
573	        case .ollama:
574	            await OllamaService.shared.checkConnection()
575	            if OllamaService.shared.isConnected {
576	                await OllamaService.shared.refreshModels()
577	            }
578	        default:
579	            if provider.isCloud {
580	                await CloudAIService.shared.refreshModels(for: provider)
581	            }
582	        }
583	    }
584	
585	    /// Select the first available Ollama model if none is selected.
586	    func selectDefaultModelIfNeeded() {
587	        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
588	            ollamaModel = firstModel.name
589	        }
590	    }
591	
592	    /// Reset to default settings.
593	    func resetToDefaults() {
594	        provider = .appleIntelligence
595	        ollamaModel = "gpt-oss:20b"
596	        ollamaHost = "http://localhost:11434"
597	        enableThinking = true
598	        contextLength = 128000
599	        aiPhotoCleanupEnabled = false
600	    }
601	
602	    // MARK: - Persistence Helpers
603	
604	    private func persistDictionary(_ dict: [String: String], key: String) {
605	        if let data = try? JSONEncoder().encode(dict) {
606	            UserDefaults.standard.set(data, forKey: key)
607	        }
608	    }
609	
610	    private static func loadDictionary(key: String) -> [String: String] {
611	        guard let data = UserDefaults.standard.data(forKey: key),
612	              let dict = try? JSONDecoder().decode([String: String].self, from: data) else {
613	            return [:]
614	        }
615	        return dict
616	    }
617	}
618	
619	// MARK: - Ollama Import
620	
621	import Ollama
