800	    /// Translate the headword into the user's native language (the headword's
801	    /// own language decides the direction, since it can be either).
802	    private func fetchTranslation() async {
803	        isLoadingTranslation = true
804	
805	        do {
806	            let headword = term.headlineText
807	            let translation = try await WordTranslationService.shared
808	                .translate(headword, sourceIsChinese: headword.containsCJK)
809	            await MainActor.run {
810	                fetchedTranslation = translation
811	                isLoadingTranslation = false
812	            }
813	        } catch {
814	            await MainActor.run {
815	                isLoadingTranslation = false
816	            }
817	            print("Failed to fetch translation: \(error)")
818	        }
819	    }
820	    
821	    private func updateTermDefinition() {
822	        // Create updated term with new definition
823	        let updatedTerm = SavedTerm(
824	            id: term.id,
825	            chinese: term.chinese,
826	            pinyin: term.pinyin,
827	            definition: fetchedTranslation,
828	            partOfSpeech: term.partOfSpeech,
829	            dateAdded: term.dateAdded,
830	            isMastered: term.isMastered
831	        )
832	        
833	        // The term may have been deleted while this sheet was open; in that
834	        // case don't pretend the edit succeeded.
835	        guard savedTermsStore.update(updatedTerm) else { return }
836	        selectedTerm = savedTermsStore.term(withID: term.id)
837	        triggerHaptic()
838	    }
839	
840	    private func triggerHaptic() {
841	        #if os(iOS)
842	        let hapticEnabled = UserDefaults.standard.bool(forKey: "hapticFeedback")
843	        if hapticEnabled {
844	            let generator = UIImpactFeedbackGenerator(style: .light)
845	            generator.impactOccurred()
846	        }
847	        #endif
848	    }
849	}
