                                    .foregroundStyle(.tertiary)
                            }
                            .contentShape(Rectangle())
                        }
                        .buttonStyle(.plain)
                    }
                } header: {
                    Text("Export To")
                }
            }
            .formStyle(.grouped)
        }
        .frame(minWidth: 420, idealWidth: 480, minHeight: 480, idealHeight: 520)
        .overlay {
            if showExportSuccess {
                exportSuccessOverlay
            }
        }
    }

    private var exportSuccessOverlay: some View {
        VStack(spacing: 12) {
            Image(systemName: "checkmark.circle.fill")
                .font(.system(size: 50))
                .foregroundStyle(.green)
            Text(exportSuccessMessage)
                .font(.headline)
        }
        .padding(24)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 16))
        .transition(.scale.combined(with: .opacity))
    }
}

// MARK: - Format Card

private struct FormatCard: View {
    let format: VocabularyExportFormat
    let isSelected: Bool
    let action: () -> Void

    private var formatDescription: String {
        switch format {
        case .json:
            return "Best for backup"
        case .csv:
            return "For spreadsheets"
        }
    }

    private var formatIcon: String {
        switch format {
        case .json:
            return "doc.text"
        case .csv:
            return "tablecells"
        }
    }

    var body: some View {
        Button(action: action) {
            VStack(spacing: 8) {
                Image(systemName: formatIcon)
                    .font(.title)
                    .foregroundStyle(isSelected ? .white : .blue)

                Text(format.rawValue)
                    .font(.headline)
                    .foregroundStyle(isSelected ? .white : .primary)

                Text(formatDescription)
                    .font(.caption2)
                    .foregroundStyle(isSelected ? .white.opacity(0.8) : .secondary)
                    .multilineTextAlignment(.center)
            }
            .frame(maxWidth: .infinity)
            .padding(.vertical, 12)
            .padding(.horizontal, 8)
            .background(
                RoundedRectangle(cornerRadius: 10)
                    .fill(isSelected ? AnyShapeStyle(.blue) : AnyShapeStyle(.quaternary.opacity(0.5)))
            )
            .overlay(
                RoundedRectangle(cornerRadius: 10)
                    .strokeBorder(isSelected ? AnyShapeStyle(.clear) : AnyShapeStyle(.quaternary), lineWidth: 1)
            )
        }
        .buttonStyle(.plain)
    }
}

// MARK: - Export Action Row

private struct ExportActionRow: View {
    let icon: String
    let iconColor: Color
    let title: String
    let subtitle: String
    let action: () -> Void

    var body: some View {
        Button(action: action) {
            HStack(spacing: 12) {
