export const meta = {
  name: 'swiftmandarin-edge-audit',
  description: 'Audit existing SwiftMandarin code for real, verified bugs and edge cases',
  phases: [
    { title: 'Find', detail: 'parallel finders per dimension' },
    { title: 'Verify', detail: 'adversarially verify each finding' },
  ],
}

const ROOT = '/Users/rogerlin/XCode-Projects/SwiftMandarinShortcuts/SwiftMandarin'

const FINDING_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string', description: 'path relative to repo' },
          line: { type: 'integer', description: 'approximate line number' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          title: { type: 'string' },
          description: { type: 'string', description: 'what is wrong and the concrete trigger/scenario' },
          suggestedFix: { type: 'string' },
        },
        required: ['file', 'severity', 'title', 'description', 'suggestedFix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    isReal: { type: 'boolean', description: 'true only if you confirmed the bug by reading the actual code' },
    severity: { type: 'string', enum: ['high', 'medium', 'low'] },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    rationale: { type: 'string', description: 'cite the exact code that proves or refutes it' },
    fix: { type: 'string' },
  },
  required: ['isReal', 'severity', 'confidence', 'rationale', 'fix'],
}

const DIMENSIONS = [
  { key: 'concurrency', prompt: `Audit Swift concurrency & actor isolation in the SwiftMandarin app at ${ROOT}. Focus on: misuse of Task{}/Task.detached, @MainActor isolation correctness, data races on shared @Observable singletons, DispatchQueue.main.asyncAfter capturing dismiss/state, unstructured tasks that outlive views, cancellation handling. Read Services/*.swift, Models/*Store*.swift, and Views that launch Tasks.` },
  { key: 'swiftui-state', prompt: `Audit SwiftUI state & observation bugs in ${ROOT}. Focus on: stale @State after model changes, .task(id:) reset logic, sheet/.inspector/.popover(item:) lifecycle, bindings to deleted items, @Observable read patterns that won't trigger updates, selectedTerm desync. Read Views/VocabularyView.swift, Views/Components/AIWordExplanationView.swift, ContentView.swift, Views/MoreView.swift.` },
  { key: 'persistence', prompt: `Audit persistence & data integrity in ${ROOT}. Focus on: UserDefaults JSON stores (PersistentCodableStore), didSet save storms / O(n^2) writes, duplicate detection & normalization, decode migration tolerance, data-loss on corrupt payloads. Read Models/PersistentCodableStore.swift, Models/SavedTerm.swift, Models/WordExplanationCacheStore.swift, Models/TranslationHistory.swift, Models/AIModelSettings.swift.` },
  { key: 'ai-cache', prompt: `Audit AI provider routing & explanation cache correctness in ${ROOT}. Focus on: directionToken cache key consistency between AIWordExplanationView and the cache store, provider/model selection fallbacks, JSON extraction/repair edge cases, vision model selection, in-memory vs persistent cache divergence. Read Services/AIWordExplanationService.swift, Services/CloudAIService.swift, Models/WordExplanationCacheStore.swift, Models/AIModelSettings.swift.` },
  { key: 'import-export', prompt: `Audit vocabulary import/export correctness in ${ROOT}. Focus on: CSV parsing edge cases (quoted fields with embedded newlines, trailing commas, CRLF, empty cells), CSV escaping, JSON date strategy round-trip, duplicate handling on import, file security scope. Read Services/VocabularyImportExportService.swift and its call sites in Views/VocabularyView.swift and Views/MacOSSettingsView.swift.` },
  { key: 'platform', prompt: `Audit iOS 17 / macOS platform gating in ${ROOT}. Focus on: #available checks for FoundationModels (iOS 26), iOS 18-only APIs (Tab builder), AppKit/UIKit #if os branches, deployment-target API misuse, SF Symbols availability. Read Views/Components/CompatModifiers.swift, ContentView.swift, Services/AIWordExplanationService.swift, and any view using @available.` },
  { key: 'localization', prompt: `Audit localization completeness in ${ROOT}. Focus on: user-facing English string literals that are NOT localized (e.g., print/log are fine; Text()/Label()/String(localized:) matter), strings that won't appear in Localizable.xcstrings, modal surfaces missing .localizedSurface(). Spot-check Views/*.swift. Report only genuinely user-visible untranslated strings.` },
  { key: 'error-ux', prompt: `Audit error handling & UX edge cases in ${ROOT}. Focus on: silent catches that swallow errors, force-unwraps (try!, as!, URL(string:)!), empty/zero states, unbounded loops/timeouts, user-facing failures reported as success. Read Services/*.swift and Views/*.swift broadly.` },
]

phase('Find')
const results = await pipeline(
  DIMENSIONS,
  (d) => agent(d.prompt, { label: `find:${d.key}`, phase: 'Find', schema: FINDING_SCHEMA, agentType: 'Explore' }),
  (res, d) => {
    const findings = (res && res.findings) || []
    return parallel(findings.map((f) => () =>
      agent(
        `You are a skeptical Swift/SwiftUI reviewer. A prior pass claims this issue in the SwiftMandarin codebase at ${ROOT}:\n\n` +
        `File: ${f.file} (~line ${f.line})\nSeverity claimed: ${f.severity}\nTitle: ${f.title}\nDescription: ${f.description}\nSuggested fix: ${f.suggestedFix}\n\n` +
        `Open the actual file and read the relevant code. Decide if this is a REAL bug/edge that a careful engineer would fix. Default to isReal=false if the code already handles it or the claim is speculative. Cite exact code in your rationale.`,
        { label: `verify:${d.key}:${(f.file || '').split('/').pop()}`, phase: 'Verify', schema: VERDICT_SCHEMA, agentType: 'Explore' }
      ).then((v) => ({ ...f, dimension: d.key, verdict: v }))
    ))
  }
)

const confirmed = results
  .flat()
  .filter(Boolean)
  .filter((f) => f.verdict && f.verdict.isReal)
  .sort((a, b) => {
    const rank = { high: 0, medium: 1, low: 2 }
    return rank[a.verdict.severity] - rank[b.verdict.severity]
  })

log(`Confirmed ${confirmed.length} real issues across ${DIMENSIONS.length} dimensions`)

return {
  confirmedCount: confirmed.length,
  byDimension: DIMENSIONS.map((d) => ({ dimension: d.key, count: confirmed.filter((f) => f.dimension === d.key).length })),
  issues: confirmed.map((f) => ({
