struct ImportResult {
    let imported: Int
    let skipped: Int
    let errors: [String]

    var summary: String {
        var parts: [String] = []
        if imported > 0 {
            parts.append("\(imported) word\(imported == 1 ? "" : "s") imported")
        }
        if skipped > 0 {
            parts.append("\(skipped) duplicate\(skipped == 1 ? "" : "s") skipped")
        }
        if errors.isEmpty {
            return parts.joined(separator: ", ")
        } else {
            return parts.joined(separator: ", ") + ". Errors: \(errors.count)"
        }
    }
